<?php
require_once __DIR__ . '/../config/CommunityService.php';
$community = new CommunityService();
if (!$community->isGlobalAdmin((int) ($_SESSION['user_id'] ?? 0))) {
    http_response_code(403);
    echo '<div class="alert alert-warning">Esta área é exclusiva da administração global da plataforma.</div>';
    return;
}
$requests = $community->listGlobalPendingLeadership();
$publicSubmissions = $community->listPendingPublicTenantSubmissions();
$tenants = $community->listTenantsForGlobalAdmin();
$success = $_SESSION['flash_success'] ?? null; unset($_SESSION['flash_success']);
$error = $_SESSION['flash_error'] ?? null; unset($_SESSION['flash_error']);
?>
<section class="mb-4"><span class="mt-eyebrow">Administração global</span><h1 class="mt-page-title">Proteção e supervisão da comunidade</h1><p class="mt-subtitle">Esta prerrogativa é exclusiva da administração global: validar pedidos de dirigente, acompanhar as casas cadastradas, moderar a publicação e prestar suporte quando necessário.</p></section>
<?php if ($success): ?><div class="alert alert-success"><?php echo e($success); ?></div><?php endif; ?><?php if ($error): ?><div class="alert alert-danger"><?php echo e($error); ?></div><?php endif; ?>
<section class="card border-0 shadow-sm"><div class="card-body p-4"><h2 class="h4 mb-3">Centros cadastrados sem login</h2><p class="text-muted">Estes cadastros não estão visíveis no diretório enquanto aguardam sua decisão. Revise as informações públicas e o contato informado antes de aprovar.</p><?php if (!$publicSubmissions): ?><p class="text-muted mb-0">Não há centros aguardando aprovação global.</p><?php else: ?><div class="vstack gap-3"><?php foreach ($publicSubmissions as $submission): ?><article class="border rounded-4 p-3"><div class="d-flex flex-column flex-xl-row justify-content-between gap-3"><div><span class="badge text-bg-warning mb-2">Aguardando aprovação</span><h3 class="h5 mb-1"><?php echo e($submission['nome_exibicao']); ?></h3><p class="mb-1"><strong>Responsável:</strong> <?php echo e($submission['solicitante_cadastro_nome']); ?> · <?php echo e($submission['email_responsavel']); ?></p><p class="mb-1"><strong>Localidade pública:</strong> <?php echo e($submission['cidade_publica']); ?>, <?php echo e($submission['estado_publico']); ?></p><?php if ($submission['nacao_publica']): ?><p class="mb-1"><strong>Tradição informada:</strong> <?php echo e($submission['nacao_publica']); ?></p><?php endif; ?><?php if ($submission['horarios_publicos']): ?><p class="mb-1"><strong>Horários públicos:</strong> <?php echo nl2br(e($submission['horarios_publicos'])); ?></p><?php endif; ?><?php if ($submission['descricao_publica']): ?><p class="small mb-0"><strong>Apresentação:</strong> <?php echo nl2br(e($submission['descricao_publica'])); ?></p><?php endif; ?></div><form class="mt-decision-form" method="post" action="public_tenant_decision.php"><input type="hidden" name="csrf_token" value="<?php echo e($csrfToken); ?>"><input type="hidden" name="tenant_id" value="<?php echo (int) $submission['id']; ?>"><label class="visually-hidden" for="center-note-<?php echo (int) $submission['id']; ?>">Observação da decisão</label><textarea class="form-control form-control-sm mb-2" id="center-note-<?php echo (int) $submission['id']; ?>" name="note" rows="3" maxlength="1000" placeholder="Observação da decisão, se aplicável"></textarea><div class="d-flex gap-2"><button class="btn btn-success btn-sm" name="decision" value="approve" type="submit">Aprovar e publicar</button><button class="btn btn-outline-danger btn-sm" name="decision" value="reject" type="submit">Recusar</button></div></form></div></article><?php endforeach; ?></div><?php endif; ?></div></section>
<section class="card border-0 shadow-sm mt-4"><div class="card-body p-4"><h2 class="h4 mb-3">Pedidos de reconhecimento de dirigente</h2><?php if (!$requests): ?><p class="text-muted mb-0">Não há pedidos pendentes de reconhecimento de dirigente.</p><?php else: ?><div class="vstack gap-3"><?php foreach ($requests as $request): ?><article class="border rounded-4 p-3"><div class="d-flex flex-column flex-xl-row justify-content-between gap-3"><div><span class="badge text-bg-warning mb-2">Pendente de verificação</span><h3 class="h5 mb-1"><?php echo e($request['nome']); ?> <span class="text-muted fw-normal">— <?php echo e($request['papel']); ?></span></h3><p class="mb-1"><strong>Casa:</strong> <?php echo e($request['nome_exibicao']); ?></p><p class="small mb-1"><?php echo e($request['email']); ?></p><p class="small mb-0">Recebido em <?php echo e(date('d/m/Y H:i', strtotime($request['solicitado_em']))); ?></p><?php if ($request['solicitacao']): ?><p class="mt-2 mb-0"><strong>Declaração:</strong> <?php echo nl2br(e($request['solicitacao'])); ?></p><?php endif; ?></div><form class="mt-decision-form" method="post" action="membership_decision.php"><input type="hidden" name="csrf_token" value="<?php echo e($csrfToken); ?>"><input type="hidden" name="membership_id" value="<?php echo (int) $request['id']; ?>"><input type="hidden" name="return_page" value="admin-global"><label class="visually-hidden" for="admin-note-<?php echo (int) $request['id']; ?>">Justificativa da decisão</label><textarea class="form-control form-control-sm mb-2" id="admin-note-<?php echo (int) $request['id']; ?>" name="note" rows="3" maxlength="1000" placeholder="Observação de decisão, se aplicável"></textarea><div class="d-flex gap-2"><button class="btn btn-success btn-sm" name="decision" value="approve" type="submit">Reconhecer</button><button class="btn btn-outline-danger btn-sm" name="decision" value="reject" type="submit">Recusar</button></div></form></div></article><?php endforeach; ?></div><?php endif; ?></div></section>
<section class="card border-0 shadow-sm mt-4"><div class="card-body p-4"><div class="d-flex flex-wrap justify-content-between align-items-center gap-2 mb-3"><div><h2 class="h4 mb-1">Supervisão de todas as casas</h2><p class="small text-muted mb-0">Ocultar remove a casa do diretório. Suspender bloqueia o centro e suas novas solicitações. Excluir é irreversível e cria um backup privado antes de remover o banco isolado.</p></div><span class="badge text-bg-dark"><?php echo count($tenants); ?> casa(s)</span></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Casa</th><th>Status</th><th>Dirigência</th><th>Participação</th><th><span class="visually-hidden">Ação</span></th></tr></thead><tbody><?php foreach ($tenants as $tenant): ?><tr><td><strong><?php echo e($tenant['nome_exibicao']); ?></strong><br><span class="small text-muted"><?php echo e(trim(($tenant['cidade_publica'] ?? '') . (($tenant['estado_publico'] ?? '') ? ' · ' . $tenant['estado_publico'] : '')) ?: 'Localidade não publicada'); ?></span><br><span class="small text-muted">Slug: <?php echo e($tenant['slug']); ?></span></td><td><span class="badge text-bg-<?php echo $tenant['status'] === 'Ativo' ? 'success' : ($tenant['status'] === 'Suspenso' ? 'warning' : 'secondary'); ?>"><?php echo e($tenant['status']); ?></span><br><span class="small text-muted"><?php echo $tenant['listar_publicamente'] ? 'No diretório' : 'Oculta'; ?></span></td><td><span class="small"><?php echo e($tenant['dirigente_status']); ?></span></td><td><span class="small"><?php echo (int) $tenant['membros_ativos']; ?> ativo(s) · <?php echo (int) $tenant['pendencias']; ?> pendência(s)</span></td><td><form method="post" action="select_tenant.php" class="mb-2"><input type="hidden" name="csrf_token" value="<?php echo e($csrfToken); ?>"><input type="hidden" name="tenant_id" value="<?php echo (int) $tenant['id']; ?>"><button class="btn btn-outline-primary btn-sm w-100" type="submit">Abrir casa</button></form><details><summary class="btn btn-outline-secondary btn-sm w-100">Moderar</summary><div class="border rounded-3 p-2 mt-2 bg-light"><div class="d-grid gap-2"> <?php if ($tenant['status'] === 'Ativo' && $tenant['listar_publicamente']): ?><form method="post" action="tenant_moderation.php"><input type="hidden" name="csrf_token" value="<?php echo e($csrfToken); ?>"><input type="hidden" name="tenant_id" value="<?php echo (int) $tenant['id']; ?>"><input type="hidden" name="action" value="hide"><button class="btn btn-outline-secondary btn-sm w-100" type="submit">Ocultar do diretório</button></form><?php elseif ($tenant['status'] === 'Ativo'): ?><form method="post" action="tenant_moderation.php"><input type="hidden" name="csrf_token" value="<?php echo e($csrfToken); ?>"><input type="hidden" name="tenant_id" value="<?php echo (int) $tenant['id']; ?>"><input type="hidden" name="action" value="publish"><button class="btn btn-outline-success btn-sm w-100" type="submit">Publicar no diretório</button></form><?php endif; ?><?php if ($tenant['status'] === 'Ativo'): ?><form method="post" action="tenant_moderation.php"><input type="hidden" name="csrf_token" value="<?php echo e($csrfToken); ?>"><input type="hidden" name="tenant_id" value="<?php echo (int) $tenant['id']; ?>"><input type="hidden" name="action" value="suspend"><input type="hidden" name="reason" value="Suspensão aplicada pela administração global."><button class="btn btn-outline-warning btn-sm w-100" type="submit">Suspender centro</button></form><?php elseif ($tenant['status'] === 'Suspenso'): ?><form method="post" action="tenant_moderation.php"><input type="hidden" name="csrf_token" value="<?php echo e($csrfToken); ?>"><input type="hidden" name="tenant_id" value="<?php echo (int) $tenant['id']; ?>"><input type="hidden" name="action" value="reactivate"><button class="btn btn-outline-success btn-sm w-100" type="submit">Reativar e publicar</button></form><?php endif; ?></div><hr class="my-3"><p class="small text-danger mb-2"><strong>Exclusão definitiva.</strong> Um backup SQL privado será criado antes de remover o banco isolado. Não use para simples retirada do diretório.</p><form method="post" action="tenant_moderation.php"><input type="hidden" name="csrf_token" value="<?php echo e($csrfToken); ?>"><input type="hidden" name="tenant_id" value="<?php echo (int) $tenant['id']; ?>"><input type="hidden" name="action" value="delete"><label class="form-label small" for="confirm-<?php echo (int) $tenant['id']; ?>">Digite <code>EXCLUIR <?php echo e($tenant['slug']); ?></code></label><input class="form-control form-control-sm mb-2" id="confirm-<?php echo (int) $tenant['id']; ?>" name="confirmation" required autocomplete="off" placeholder="EXCLUIR <?php echo e($tenant['slug']); ?>"><label class="form-label small" for="reason-<?php echo (int) $tenant['id']; ?>">Motivo obrigatório</label><textarea class="form-control form-control-sm mb-2" id="reason-<?php echo (int) $tenant['id']; ?>" name="reason" rows="3" minlength="10" maxlength="1000" required placeholder="Descreva o motivo da exclusão definitiva"></textarea><button class="btn btn-danger btn-sm w-100" type="submit">Excluir definitivamente</button></form></details></td></tr><?php endforeach; ?></tbody></table></div></div></section>
